import json, re, html
from pathlib import Path
S=json.loads(Path('source.json').read_text())
R=json.loads(Path('reference-targets.json').read_text())
A=[]
def paras(*p): return '\n'.join('<p>'+x+'</p>' for x in p)
def plain(x): return html.unescape(re.sub('<[^>]*>', '', x or ''))
def replace(x,old,new):
    assert x.count(old)==1, (old, x.count(old))
    return x.replace(old,new)
def effect(kind,mid,desc,before,after,unit,pop,transition,burdens,source,proposed):
    return dict(kind=kind,measure_id=mid,description=desc,before=before,after=after,unit=unit,affected_population=pop,conditions_and_transition=transition,replacement_or_new_burdens=burdens,source_quote=source,proposed_quote=proposed)
def emit(i,proposed,reason,notes,classification,assessment,limits,new,ef=None,**extra):
    s=S[i];a={k:s[k] for k in ['code_id','source_id','source_sha256','number']}
    a.update(proposed_xml=proposed,reason=reason,review_notes=notes,status='retained_unchanged' if proposed is None else 'rewrite_draft')
    if proposed is None: a['classification']='retained_necessary'
    a.update(extra)
    a['substantive_impact']=dict(version=1,classification=classification,assessment=assessment,scope_limitations=limits,new_burdens_review=new,effects=ef or [])
    A.append(a)
old_repeal='Les actes, dépôts et notifications régulièrement accomplis avant cette date conservent leurs effets. Les contrôles, créances, prescriptions et recours relatifs aux impositions antérieures demeurent régis par les dispositions qui leur sont applicables. Les sanctions non définitives restent soumises aux règles de la loi répressive plus douce.'
# 223 ter : suppression du relevé autonome, sans suppression des régimes de presse.
p=paras("Le présent article est abrogé à compter de l'entrée en vigueur de la présente loi. Aucun relevé distinct des dépenses effectuées par prélèvement sur les bénéfices ou sur les provisions de presse n'est exigé, sur ce fondement, à compter de cette date, y compris au titre d'une période antérieure. Aucun dépôt de rattrapage de ce relevé n'est exigé.",
"Les déductions, franchises et provisions prévues aux articles 39 bis à 39 bis B demeurent applicables aux entreprises, dépenses et périodes qui remplissent leurs conditions, y compris aux situations futures éligibles. Leur bénéfice ne peut être refusé pour la seule absence du relevé supprimé. Les conditions de fond, les plafonds, les règles d'emploi et de reprise des provisions ainsi que les règles évitant une double déduction demeurent applicables. Les pièces comptables ordinaires peuvent en établir le respect dans le cadre des contrôles légalement prévus, sans état périodique de remplacement.",old_repeal)
emit(0,p,"Réforme de fond : suppression du relevé autonome joint à chaque déclaration d'IS, qui reproduit des emplois de bénéfices et provisions traçables en comptabilité. Les régimes favorables de presse ne sont pas abrogés ; les règles d'emploi et de reprise restent contrôlables. Ce retrait de dépôt est distinct du report d'exigibilité de l'IS.","39 bis et sa proposition ont été lus dans la vue fournie ; les sources intégrales 39 bis A et 39 bis B ont été consultées dans impots.json du corpus autorisé. Leurs limites de période, plafonds et de minimis ne sont ni prolongés ni supprimés par cet article. Coordonner les modèles et prescriptions réglementaires qui exigent exclusivement ce relevé et les éventuelles sanctions documentaires du LPF ; aucune nouvelle pièce n'est créée. Le 2 de 39 bis porte une ancienneté historique de salariés, non le seuil du contrat unique : aucun recalcul d'indemnité n'est décidé ici.",
'material_reduction',"Le relevé obligatoire à chaque déclaration est effectivement retiré pour toute transmission future, tandis que l'accès aux avantages de presse et leur contrôle sur pièces ordinaires subsistent.","Les obligations comptables et les déclarations générales d'IS ne sont pas supprimées ; le coût du dépôt retiré n'est pas chiffré et les modèles extérieurs au lot restent à coordonner.","Aucune charge nouvelle n'est identifiée : le relevé disparaît sans formulaire, déclaration, attestation ni registre de remplacement ; les preuves ordinaires existent déjà.",[
effect('obligation_removed','presse-suppression-releve-depenses','Retrait du relevé spécifique de dépenses de presse joint aux déclarations d’IS.','Relevé distinct à chaque déclaration d’IS pour les personnes morales utilisant les articles 39 bis à 39 bis B.','Aucun relevé ni rattrapage exigé après entrée en vigueur, même pour les périodes anciennes.','legal_duty','Sociétés et autres personnes morales bénéficiaires des régimes de presse.','Transmissions futures ; avantages, règles de fond et contrôles anciens et futurs conservés.','Aucun état périodique de remplacement.',"sont tenues de joindre à chaque déclaration qu'elles souscrivent pour l'établissement de l'impôt sur les sociétés, un relevé", "Aucun dépôt de rattrapage de ce relevé n'est exigé.")],change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope="Suppression de l'obligation autonome de joindre aux déclarations d'IS un relevé des dépenses prélevées sur les bénéfices et provisions de presse, sans retrait des déductions concernées.")
# 223 quater : conserver la traçabilité des dépenses personnelles, supprimer le vote annuel spécifique.
x=S[1]['source_xml']
x=replace(x,"Ces entreprises doivent soumettre chaque année à l'approbation de l'assemblée générale ordinaire de leurs actionnaires ou associés le montant global des dépenses et charges dont il s'agit, ainsi que de l'impôt supporté en raison de ces dépenses et charges.","Aucune approbation annuelle particulière de ces dépenses et charges et de l'impôt correspondant par l'assemblée générale ordinaire n'est exigée sur le fondement du présent article.")
x+=paras("La suppression de cette approbation s'applique aux assemblées tenues à compter de l'entrée en vigueur de la présente loi, même lorsqu'elles examinent des comptes antérieurs. Elle ne dispense pas d'une autorisation, d'une information ou d'un contrôle fondés sur une disposition autonome du droit des sociétés. Les décisions antérieures, les droits des associés, les obligations comptables et les contrôles fiscaux conservent leurs effets. Le présent article ne fait pas naître un IS annuel sur des bénéfices conservés relevant du régime de distribution des V et VI de l'article 219.")
emit(1,x,"Réforme de fond ciblée : retrait du vote annuel spécial sur les dépenses du 4 de l'article 39 et leur impôt, sans rapport de remplacement. La distinction comptable est maintenue pour identifier les charges exclues et les avantages personnels susceptibles d'être des distributions ; elle n'est pas remplacée par une nouvelle déclaration.","Le 4 de 39 conserve les exceptions à caractère social et professionnel, les seuils automobiles et les justifications ; 206 exclut toujours son 5 du présent article. Aucun avantage n'est supprimé. L'article 219, cible non fournie dans reference-targets, a été consulté dans le corpus pour ses V et VI ; le vote n'est pas rétabli par la nouvelle exigibilité. Les procédures autonomes du code de commerce restent hors de cette suppression et doivent être distinguées dans les modèles d'assemblée.",
'material_reduction',"L'article entier conserve le repérage comptable utile, mais retire une approbation obligatoire récurrente distincte de l'approbation des comptes. Il ne réduit pas à lui seul le taux ou l'assiette de l'IS.","Le droit des sociétés peut exiger d'autres autorisations ou informations ; elles ne sont pas réputées abolies. Les coûts privés et le solde public ne sont pas chiffrés.","Aucune charge nouvelle n'est identifiée : le vote particulier est supprimé sans envoi, visa ou rapport de remplacement ; la comptabilité distincte reste celle de la source.",[
effect('obligation_removed','is-depenses-somptuaires-fin-vote-annuel','Suppression de l’approbation annuelle spécifique, avec traçabilité comptable maintenue.','Vote annuel de l’assemblée ordinaire sur le montant global des dépenses du 4 de 39 et de leur impôt.','Plus de vote obligatoire sur ce seul fondement pour les assemblées futures.','legal_duty','Personnes morales passibles de l’IS hors 5 de 206, entreprises nationales comprises.','Assemblées tenues après entrée en vigueur, y compris sur des comptes anciens.','Les procédures autonomes de droit des sociétés ne sont pas supprimées.',"Ces entreprises doivent soumettre chaque année à l'approbation de l'assemblée générale ordinaire de leurs actionnaires ou associés le montant global des dépenses et charges dont il s'agit, ainsi que de l'impôt supporté en raison de ces dépenses et charges.","Aucune approbation annuelle particulière de ces dépenses et charges et de l'impôt correspondant par l'assemblée générale ordinaire n'est exigée sur le fondement du présent article.")],change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=["Approbation annuelle particulière par l'assemblée générale ordinaire du montant des dépenses du 4 de 39 et de l'impôt correspondant."])
# 223 quinquies : seconde communication de chiffres déjà établis.
p=paras("Le présent article est abrogé à compter de l'entrée en vigueur de la présente loi. La communication particulière à la plus proche assemblée générale, sous la responsabilité des commissaires aux comptes, des chiffres globaux des catégories de dépenses visées au 5 de l'article 39 n'est plus obligatoire sur ce fondement. Cette suppression s'applique à toute communication non encore accomplie à cette date, y compris lorsque la demande de justification de l'administration ou l'exercice concerné lui est antérieur.","Le relevé fiscal prévu à l'article 54 quater, les conditions de déduction des dépenses, le pouvoir de demander les justifications prévues au 5 de l'article 39 et les missions des commissaires aux comptes ayant un fondement autonome demeurent régis par leurs dispositions propres. Aucun rapport ou dépôt ne remplace la communication supprimée. Les communications déjà effectuées et les droits et recours relatifs aux exercices antérieurs conservent leurs effets.")
emit(2,p,"Réforme de fond : retrait de la seconde communication à l'assemblée de chiffres déjà concernés par le relevé fiscal et le contrôle des frais généraux. Le retrait de ce circuit spécifique ne supprime ni l'intérêt de l'entreprise comme critère de déduction ni la responsabilité autonome des commissaires aux comptes.","Le dixième alinéa du 5 de 39 vise la demande de justification lorsque les frais croissent plus vite que le bénéfice ou l'excèdent ; il ne vise aucune notification de licenciement. Le relevé 54 quater et sa proposition ont été lus dans le corpus, cible non fournie dans reference-targets. Coordonner les modèles de rapports des commissaires aux comptes sans supprimer leurs missions légales distinctes ni les garanties des associés.",
'material_reduction',"La communication supplémentaire obligatoire à l'assemblée est retirée ; les informations fiscales et le contrôle substantiel des dépenses restent disponibles sans circuit de remplacement.","Les obligations autonomes du code de commerce et le relevé 54 quater ne sont pas supprimés ; aucun gain budgétaire ou baisse d'impôt n'est démontré par cette seule coupe.","Aucune charge nouvelle n'est identifiée : le circuit de communication disparaît et aucune déclaration, attestation ou formalité de substitution n'est imposée.",[
effect('obligation_removed','is-frais-generaux-fin-communication-assemblee','Retrait de la communication spéciale des frais généraux à l’assemblée.','Chiffres globaux du relevé 54 quater communiqués à l’assemblée sous responsabilité des commissaires aux comptes.','Aucune communication spéciale encore à accomplir après entrée en vigueur.','legal_duty','Sociétés auxquelles l’administration demande les justifications du 5 de 39.','Démarches futures, y compris pour les exercices antérieurs ; missions autonomes et relevé fiscal conservés.','Aucun rapport ou dépôt de substitution.',"sont communiqués à la plus proche assemblée générale des actionnaires sous la responsabilité des commissaires aux comptes.","Aucun rapport ou dépôt ne remplace la communication supprimée.")],change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope="Suppression de la communication particulière obligatoire à l'assemblée générale des frais généraux recensés pour le contrôle fiscal, sous la responsabilité des commissaires aux comptes.")
# 223 quinquies A : représentation fiscale obligatoire.
p=paras("Le présent article est abrogé à compter de l'entrée en vigueur de la présente loi. Aucune désignation ni aucun maintien d'un représentant en France ne peut être exigé sur son fondement à compter de cette date des personnes morales désignées au 2 de l'article 218 A, quel que soit l'Etat ou le territoire de leur siège. Les demandes antérieures de désignation qui n'ont pas encore été exécutées cessent de produire cet effet ; aucun délai de désignation ne continue à courir.","Les impositions, obligations de paiement, garanties de procédure et voies de recours demeurent régies par leurs dispositions propres. Les communications fiscales peuvent être reçues directement par leur destinataire ou par un mandataire volontaire dans les conditions légales de notification, sans représentant ni domicile français obligatoire de remplacement. Les mandats valablement consentis restent soumis à leurs stipulations et aux règles de révocation. La validité des communications régulièrement reçues avant l'entrée en vigueur et les délais de recours qu'elles ont ouverts ne sont pas remis en cause. Les conséquences répressives de manquements antérieurs non définitivement jugés restent soumises aux règles de la loi répressive plus douce.")
emit(3,p,"Réforme de fond : suppression de la représentation fiscale de réception imposable sur demande dans un délai de quatre-vingt-dix jours aux personnes morales étrangères hors dispense UE/EEE. La dispense devient générale ; la réception directe et le mandat volontaire ne créent aucune formalité obligatoire de substitution.","218 A, source intégrale lue dans le corpus autorisé, fixe le lieu d'imposition et non un pouvoir général d'exiger un domicile français. La note source renvoie expressément à LPF L72 : sa conséquence de taxation d'office pour absence de représentant doit être retirée pour ce motif supprimé, y compris pour les demandes pendantes. Cette coordination hors des cinq codes est identifiée et n'est pas présentée comme rédigée. Maintenir les modes légaux de notification internationale et les conventions de recouvrement ; aucune dispense de principal fiscal ni réouverture de délai expiré n'est créée.",
'material_reduction',"Le service perd la faculté d'imposer la désignation d'un représentant local de réception ; la dispense UE/EEE est étendue à tous les sièges. Le montant des impôts reste inchangé.","La coordination du LPF L72 et des règles de notification reste indispensable ; les obligations de représentation fondées sur un autre impôt ne sont pas couvertes. Coût net non chiffré.","Aucune charge nouvelle n'est identifiée : aucune adresse française, inscription, plateforme ou déclaration ne remplace le représentant ; les notifications gardent leurs garanties légales.",[
effect('obligation_removed','is-suppression-representant-fiscal-impose','Suppression de la désignation obligatoire d’un représentant français de réception.','Sur demande du service, représentant en France à désigner sous 90 jours ; dispense UE/EEE conventionnée.','Pas de représentant obligatoire sur ce fondement pour aucun siège ; demandes pendantes sans effet.','legal_duty','Personnes morales du 2 de 218 A, principalement sièges hors UE/EEE dispensée.','Entrée en vigueur ; actes de notification passés et mandats volontaires conservés.','Aucun domicile ou représentant obligatoire de remplacement.',"un représentant en France autorisé à recevoir les communications relatives à l'assiette, au recouvrement et au contentieux de l'impôt", "aucun délai de désignation ne continue à courir.")],change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope="Suppression de la faculté d'imposer à une personne morale étrangère la désignation et le maintien d'un représentant fiscal en France chargé de recevoir les communications d'IS.")
# 223 quinquies B : dépôt simplifié annuel de prix de transfert, distinct du CbCR.
p=paras("Le présent article est abrogé à compter de l'entrée en vigueur de la présente loi. La déclaration électronique annuelle simplifiée des prix de transfert, de la politique du groupe, de ses actifs incorporels et des opérations de l'entreprise avec des entreprises associées n'est plus exigée sur son fondement. Aucun dépôt initial, rectificatif ou de rattrapage n'est exigé à compter de cette date au titre de cet article, même pour un exercice antérieur, ni de chaque personne morale ni de sa société mère.","Les règles de pleine concurrence, les rectifications de prix de transfert et les obligations de documentation et de communication ayant un fondement légal autonome demeurent applicables dans leur champ propre. La déclaration pays par pays prévue à l'article 223 quinquies C et les obligations relatives à l'imposition minimale internationale demeurent distinctes. Aucune déclaration générale périodique ne remplace celle supprimée par le présent article.","Les déclarations régulièrement souscrites restent utilisables dans les conditions légales. Les dettes d'impôt, contrôles, prescriptions et recours des exercices antérieurs ne sont pas éteints. Les sanctions non définitives restent soumises aux règles de la loi répressive plus douce ; une demande de contrôle fondée sur un texte autonome ne constitue pas un dépôt annuel de rattrapage sur le fondement abrogé.")
emit(4,p,"Réforme de fond : suppression intégrale du dépôt annuel simplifié pour le périmètre de 50 millions d'euros, ses entités liées et groupes, y compris l'état des opérations dépassant 100 000 euros et le dépôt central par la mère. Les règles et contrôles de pleine concurrence ainsi que le pays par pays restent distincts. Le retrait n'est pas présenté comme le simple réemploi de données déjà garanti par le CRPA.","Le renvoi à 223 A ne sert ici qu'à étendre le champ et centraliser un dépôt, désormais supprimé. Les obligations de documentation du LPF, notamment L13 AA et L13 AB, et les procédures des articles 57 du CGI et L13 B du LPF doivent être vérifiées dans leur champ autonome ; leurs textes ne sont pas fournis dans reference-targets ni réécrits ici. Ne pas affirmer que toutes les entités de 50 millions sont déjà couvertes par une même documentation. Coordonner formulaire 2257 et sanctions de 1729 B sans fermer 223 quinquies C, les échanges conventionnels ou le minimum international. Ni IS annuel sur bénéfices conservés ni perte de taux réduit n'est créé.",
'material_reduction',"La source entière impose un dépôt périodique national simplifié et son contenu détaillé : cette obligation disparaît, sans supprimer les contrôles ciblés ni la déclaration pays par pays maintenue dans l'article suivant.","L'existence d'un doublon parfait pour toutes les entreprises n'est pas démontrée ; le choix retire le reporting général, pas le contrôle. Compatibilité des engagements internationaux à coordonner ; aucun coût global chiffré.","Aucune charge nouvelle n'est identifiée : pas de déclaration de remplacement, de nouveau seuil, de registre ni d'attestation ; seules les obligations autonomes conservent leur champ.",[
effect('obligation_removed','prix-transfert-suppression-declaration-simplifiee','Retrait de la déclaration annuelle simplifiée des prix de transfert.','Personnes françaises avec CA HT ou actif brut ≥ 50 M€, entités de contrôle et groupes visés ; dépôt électronique à 6 mois de l’échéance de 223 ; opérations agrégées par nature > 100 000 €.','Aucun dépôt sur ce fondement après entrée en vigueur, mère et membres compris.','legal_duty','Personnes morales du I et sociétés mères déposantes du II de la source.','Transmissions futures, exercices anciens compris ; contrôles et dettes historiques préservés.','Pas de déclaration générale périodique de remplacement.',"souscrivent une déclaration, par voie électronique, dans le délai de six mois qui suit l'échéance prévue au 1 de l'article 223.","Aucune déclaration générale périodique ne remplace celle supprimée par le présent article.")],change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope="Suppression de la déclaration électronique annuelle simplifiée de prix de transfert, de ses rubriques et du dépôt pour les membres par la mère, sans retrait de la règle de pleine concurrence ni du pays par pays.")
# 223 quinquies C : outil d'échange international nécessaire, texte entier maintenu.
emit(5,None,"Maintien intégral nécessaire après examen des charges : la déclaration pays par pays des groupes multinationaux de 750 millions d'euros sert l'échange réciproque d'informations et le contrôle de la localisation des bénéfices, y compris avec un IS français à la distribution. Les exceptions de dépôt par une autre entité évitent déjà les duplications ; les douze mois sont un délai maximal de dépôt, non une attente minimale à supprimer. Le présent lot retire séparément le reporting national simplifié de 223 quinquies B.","Le texte vise des comptes consolidés, une présence étrangère et un chiffre d'affaires consolidé au moins égal à 750 millions, avec critères cumulatifs et dépôt secondaire conditionnel. Il ne fixe ni assiette d'IS annuel ni droit à exonération. La directive 2016/881 et les accords d'échange pays par pays constituent les contraintes européennes et conventionnelles à coordonner avant toute suppression ; leur conformité d'ensemble n'est pas attestée ici. Aucun renvoi au contrat unique ni assimilation au seuil du minimum international, malgré le même chiffre, n'est opéré.",
'retained_necessary',"Le reporting pays par pays est conservé dans toutes ses conditions, dispenses et modalités d'échange. Aucune baisse de prélèvement ou d'obligation nouvelle n'est attribuée à ce maintien.","L'application des accords et du droit européen demeure à contrôler hors du lot ; les dispositifs de publicité et le minimum international ont un champ autonome, non modifié ici.","Aucune charge nouvelle n'est identifiée : maintien strict du texte officiel avec ses douze mois, ses critères et ses règles de dépôt unique existantes.")
# 223 B bis : plafonds conservés, verrou décennal et dépôt autonome retirés.
x=S[6]['source_xml']
x=replace(x,"Elle est irrévocable et formulée pour une période de dix années et est renouvelable au terme de cette période.","Elle se poursuit sans renouvellement obligatoire jusqu'à sa dénonciation par la société mère, indiquée dans la déclaration de résultat de l'exercice pour lequel elle cesse de s'appliquer. Aucune durée minimale ni irrévocabilité n'est imposée.")
x=replace(x,"IX. – Un décret fixe les obligations déclaratives de la société mère du groupe mentionné au I.","IX. – Aucun état déclaratif particulier des charges financières nettes non déduites, de leur report ou des capacités de déduction inemployées n'est exigé sur le fondement du présent article, qu'il soit séparé ou joint à la déclaration de la société mère. Les calculs restent justifiables à partir de la comptabilité et des documents de suivi déjà légalement exigés, dans le cadre des contrôles existants. Aucun dépôt périodique ni modèle supplémentaire de remplacement n'est imposé sur ce fondement.")
x+=paras("X. – Les suppressions de durée minimale, d'irrévocabilité et d'état déclaratif particulier s'appliquent à compter de l'entrée en vigueur de la présente loi, y compris aux options en cours et aux dépôts non encore accomplis. Elles ne modifient ni les conditions de fond des déductions, ni le traitement des charges et capacités déjà consommées. Les exercices antérieurs, leurs droits à déduction, dettes, prescriptions et recours restent régis par les règles qui leur étaient applicables, sous réserve de ces allègements de formalité.",
"Pour les exercices relevant des V et VI de l'article 219, le présent article s'applique au résultat d'ensemble de référence, constitué pour ses seuls calculs par la somme algébrique des résultats de référence des membres du groupe avant déficits et avant application du présent article. La période de calcul est l'exercice de la société mère. Les écritures des autres membres sont retenues pour cette même période ; leur rapprochement n'impose ni modification de leurs dates de clôture ni dépôt de comptes intermédiaires. Chaque charge, produit ou correction n'est retenu qu'une fois. Les montants en euros prévus aux I et VII demeurent annualisés dans les conditions de ces subdivisions.",
"Dans ce régime, les références du II aux taux du deuxième alinéa et du b du I de l'article 219 désignent les catégories de bénéfices relevant respectivement du taux normal et du taux réduit des petites entreprises prévus au V de cet article ; elles ne rétablissent pas l'exigibilité annuelle. Les gains et pertes des catégories particulières, les déductions et les abattements restent pris en compte selon le II. Les I à VIII, leurs dérogations et les contrats historiquement éligibles restent applicables aux charges et situations futures remplissant leurs conditions ; les périodes anciennes d'éligibilité des contrats ne sont pas rouvertes.",
"La société mère répartit les charges nettes non déductibles de la période entre les membres à proportion de leurs charges financières nettes positives ayant concouru au calcul. Les reports, capacités disponibles et déductions ultérieures restent suivis par leur titulaire légal ; une même charge ou capacité n'est pas utilisée dans deux sociétés ni à la fois au niveau du groupe et d'un membre. Ces corrections sont prises en compte une seule fois dans les résultats de référence et les compartiments du XI de l'article 209, au moyen du suivi et du rapprochement annuel qu'il prévoit, sans état séparé. Elles ne constituent ni une distribution ni un bénéfice déjà imposé.",
"Le seul calcul d'un résultat d'ensemble, d'une charge non déductible, d'un report ou d'une capacité de déduction ne rend pas l'IS ordinaire exigible sur des bénéfices conservés, y compris en trésorerie. L'IS de distribution, les impositions annuelles distinctes et l'impôt minimum international restent régis par leurs dispositions propres. Le présent article n'étend pas son option d'infrastructure au régime fiscal d'une autre personne publique ou d'un autre contrat.")
emit(6,x,"Réforme de fond : suppression du verrou irrévocable de dix ans de l'option d'infrastructure et de l'état déclaratif particulier des charges et capacités, même joint à la déclaration annuelle. Les plafonds de déduction et protections contre l'érosion de l'assiette sont conservés, avec toutes leurs clauses favorables. Coordination nécessaire : le résultat d'ensemble est un calcul de référence qui ne déclenche plus l'IS ordinaire annuel ; une ventilation explicite raccorde les corrections du groupe aux compartiments individuels du nouvel IS.","Lecture complète des I à IX, y compris ratios, exceptions de trésorerie et crédit-bail, périodes des contrats et deux reports distincts. La limitation des intérêts relève notamment du cadre anti-évasion de la directive 2016/1164 : elle n'est pas abrogée ; sa compatibilité avec le fait générateur de distribution et les choix d'infrastructure doit être coordonnée, sans conformité présumée. 212 bis (source entière lue), 209 XI à XIII, 219 V/VI, 223 B et 223 I (propositions lues dans le corpus) sont des cibles non fournies dans reference-targets. L'annexe III 46 quater-0 ZL a été lue intégralement dans le corpus : son 9 impose un état joint des charges non déduites, reports et capacités, et son dernier alinéa des modèles administratifs. Coordonner le retrait de ce seul état du 9 et de son modèle, sans supprimer les autres états de cet article. Ce n'est donc pas la suppression d'une déclaration générale autonome ; les comptes de 209 ne sont pas un second gain documentaire. La ventilation nouvelle des corrections et le rapprochement sur l'exercice de la mère ont un coût inconnu. Aucun double abattement de trois millions ou de capacité inemployée n'est créé.",
'mixed',"Deux contraintes nationales sont retirées, sans supprimer les limites de déduction des intérêts. Le raccordement aux assiettes individuelles de distribution ajoute une ventilation des corrections ; le solde net de complexité n'est pas établi.","Les taux et assiettes d'IS sont réformés ailleurs. Les contraintes européennes, la concordance des calculs réglementaires et le coût du rapprochement des clôtures différentes restent à coordonner ; aucune économie globale n'est déduite.","Le verrou décennal et l'état particulier joint disparaissent. La ventilation entre membres et le rapprochement sur la période de la mère sont explicités pour les compartiments de 209 : traitement nouveau, sans nouveau registre, compte intermédiaire à déposer ou déclaration séparée. Son coût net n'est pas établi.",[
effect('obligation_removed','interets-groupe-fin-verrou-option-infrastructure','Retrait de l’engagement décennal irrévocable de l’option favorable d’infrastructure.','Option notifiée au dépôt du premier exercice, irrévocable pendant dix années.','Notification initiale conservée ; cessation indiquée dans la déclaration de l’exercice concerné, sans durée minimale ni renouvellement.','legal_duty','Sociétés mères de groupes disposant des contrats et infrastructures éligibles des IV et V.','Options futures et en cours ; ni réouverture de périodes de contrats ni recalcul des charges déjà consommées.','Aucun avis ou agrément de sortie ; indication dans la déclaration existante.',"Elle est irrévocable et formulée pour une période de dix années et est renouvelable au terme de cette période.","Aucune durée minimale ni irrévocabilité n'est imposée."),
effect('obligation_removed','interets-groupe-suppression-etat-joint','Retrait de l’état particulier joint de charges financières, reports et capacités.','État particulier prescrit sur le fondement du IX, joint à la déclaration de groupe selon le 9 de 46 quater-0 ZL.','Aucun état particulier joint ou séparé, aucun dépôt périodique de remplacement sur ce fondement.','legal_duty','Mères de groupes soumises à 223 B bis.','Dépôts non encore accomplis à l’entrée en vigueur ; pièces de calcul et contrôles conservés.','La déclaration générale et les pièces de calcul existantes demeurent ; pas de modèle périodique de remplacement.',"IX. – Un décret fixe les obligations déclaratives de la société mère du groupe mentionné au I.","Aucun dépôt périodique ni modèle supplémentaire de remplacement n'est imposé sur ce fondement."),
effect('complexity_added','is-distribution','Ventilation des corrections financières du groupe pour les compartiments individuels.','Corrections effectuées dans un résultat fiscal d’ensemble annuel.','Corrections affectées une seule fois aux résultats et compartiments individuels ; ventilation au prorata des charges nettes positives.','legal_duty','Mère et membres des groupes relevant de l’IS à la distribution.','Exercices ouverts sous le nouveau régime ; reports et capacités attachés au titulaire légal.','Calcul de ventilation supplémentaire, intégré au suivi de 209, coût non chiffré.',"Les charges financières nettes supportées par le groupe sont déductibles du résultat d'ensemble", "La société mère répartit les charges nettes non déductibles de la période entre les membres à proportion de leurs charges financières nettes positives ayant concouru au calcul.")],change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=["Irrévocabilité et engagement minimal de dix années de l'option d'infrastructure du V, y compris pour les options en cours.","État déclaratif particulier des charges financières, reports et capacités, même joint à la déclaration annuelle de la mère ; pas de modèle ou dépôt périodique de remplacement."],benefit_review="Les avantages sont conservés individuellement : I maintient le plus élevé de 3 millions d'euros annualisés et de 30 % ; II garde déductions et abattements ainsi que l'exclusion des résultats d'infrastructure sur option ; III maintient la compensation des charges et produits des membres. IV conserve les contrats historiquement admissibles, le plafond propre de 3 millions/30 % et la déduction supplémentaire de 75 %. V garde la faculté d'option et ses conditions européennes, en retirant seulement son verrou décennal. VI conserve les 75 % supplémentaires, la tolérance de deux points et la méthode commune de consolidation. VII conserve le choix ouverture/clôture des fonds propres, le plafond 1 million/10 %, le tiers reportable, les assimilations favorables de trésorerie centralisée, crédit-bail et établissements de crédit, ainsi que l'exception de ratio d'endettement et sa tolérance de deux points. VIII maintient le report des charges non déduites et la capacité inemployée de cinq exercices, avec leurs distinctions et interdiction de double emploi. X maintient ces possibilités pour les futures situations éligibles ; aucun plafond réduit ni nouvelle condition de dépense n'est créé pour conserver la trésorerie. Les exclusions qui subsistent protègent la limite anti-érosion et ne sont pas présentées comme des avantages supprimés.")
# Période des mécanismes d'ensemble favorables conservés sous le nouveau paiement par membre.
period="Pour ce calcul de référence, la période retenue est l'exercice de la société mère ; les résultats des membres sont rapprochés pour cette même période à partir des écritures comptables existantes, sans imposer une modification de leurs dates de clôture ni un dépôt de comptes intermédiaires. Aucun produit, perte ou correction n'est compté deux fois."
# 223 D : conserver la compensation, supprimer le renvoi opératoire à la réserve abrogée.
x=S[7]['source_xml']
x=replace(x,"La plus-value nette à long terme d'ensemble fait l'objet d'une imposition séparée dans les conditions prévues au a bis du I de l'article 219.","La plus-value nette à long terme d'ensemble relève de la catégorie d'imposition séparée prévue au a bis du I de l'article 219. Pour les exercices relevant des V et VI du même article, son exigibilité est reportée à la distribution dans les conditions de ces subdivisions ; son seul calcul ne rend pas l'IS ordinaire exigible.")
x=replace(x,"Le montant net d'impôt de la plus-value nette à long terme d'ensemble doit être porté, au bilan de la société mère, à la réserve spéciale prévue à l'article 209 quater.","À compter de l'entrée en vigueur de la présente loi, aucune inscription, reprise ou reconstitution de la réserve spéciale de l'ancien article 209 quater ni aucun complément d'IS fondé sur un prélèvement nouveau sur cette réserve ne sont exigés. Les sommes anciennes définitivement libérées de ce complément relèvent du compte protégé du 1 du XI de l'article 209, pour leur montant disponible non déjà consommé ou compté.")
x+=paras("Pour les exercices relevant des V et VI de l'article 219, les règles de compensation, de report, de provision et de reprise du présent article restent applicables aux groupes et opérations futurs comme aux situations antérieures. Par dérogation à la seule addition des cotisations individuelles de l'article 223 B, le calcul favorable des plus-values et moins-values à long terme d'ensemble est conservé, dans leurs catégories respectives et sans transformer une moins-value non déductible en déficit ordinaire. "+period,
"La société mère affecte la compensation effectivement utilisée aux bases des gains des membres concernés dans le suivi du XI de l'article 209 et le rapprochement annuel, dans la limite des gains de la catégorie correspondante. Les bases ainsi réduites ne sont pas déduites une seconde fois lors de leur distribution. Le reliquat de moins-value d'ensemble reste suivi par son titulaire légal avec sa durée d'origine ; il n'est pas recréé dans les filiales. La ventilation ne peut augmenter la base d'un membre au-delà de ses gains nets avant cette compensation. Aucun état supplémentaire de réserve spéciale n'est demandé.",
"Les reprises de neutralisations ou provisions anciennes suivent le compartiment correspondant de l'article 209. Elles ne rétablissent pas une cotisation annuelle d'IS ordinaire sur un bénéfice conservé ; les pertes effectivement compensées cessent d'être disponibles pour une autre imputation. Les montants déjà taxés ou définitivement exonérés sont protégés d'un second IS dans les conditions du même article. Les impositions relatives aux exercices ouverts avant l'ouverture du régime de distribution et les compléments attachés aux prélèvements intervenus avant l'entrée en vigueur restent régis par les règles antérieures, même si leur liquidation, leur exigibilité ou leur paiement est postérieur. Leurs restitutions, prescriptions et recours sont conservés, sans restitution générale d'un impôt légalement dû. Le minimum international demeure distinct.")
emit(7,x,"Coordination nécessaire de l'IS à la distribution et de la suppression déjà proposée de la réserve 209 quater : maintien intégral des calculs, compensations de moins-values, provisions et exceptions, mais retrait de l'exigibilité annuelle et de l'obligation de réserve devenue incohérente. L'avantage du calcul d'ensemble est expressément conservé pour les opérations futures malgré le nouveau paiement par membre ; une affectation empêche son double emploi.","Les sources et vues de 39 quindecies, 39 et 223 L ont été lues intégralement ; l'exception des c à j du 6 de 223 L conserve son champ ; le texte précise son application aux opérations nouvelles sans reprise des anciennes durées ou notifications annuelles. Les propositions de 209 XI/XIII, 209 quater, 219 V/VI, 223 B et 223 I ont été consultées dans le corpus : cibles non fournies dans reference-targets, sans prétendre qu'elles sont du droit en vigueur. La suppression de la réserve est une coordination de la même mesure, pas un second impôt supprimé ; l'alinéa historique de 2004 reste en place. Raccorder les modalités d'affectation des moins-values de groupe à 223 I sans retirer la compensation future. Le rapprochement de périodes et la ventilation ont un coût non chiffré ; les modalités des clôtures différentes demandent coordination réglementaire, pas de nouvelle clôture imposée.",
'mixed',"Les compensations et catégories favorables restent ouvertes. L'exigibilité est coordonnée à la distribution et la réserve spéciale supprimée ailleurs n'est pas rétablie. L'affectation des compensations aux bases individuelles est un calcul supplémentaire ; aucun solde net de complexité n'est établi.","Les taux propres des catégories de 219 et les délais de 39 quindecies ne sont pas modifiés. L'articulation réglementaire des comptes et de 223 I reste à coordonner ; aucun gain national chiffré n'est avancé.","L'inscription à la réserve spéciale n'est pas remplacée par un autre dépôt. Une ventilation des compensations et un rapprochement de périodes alimentent le suivi de 209 : charges de calcul explicitées, sans nouveau registre ni comptes intermédiaires à déposer. Leur coût net n'est pas mesuré.",[
effect('coordination','reserve-plus-values-complement-is-suppression','Ne pas recréer par 223 D la réserve spéciale et son complément supprimés dans 209 quater.','Inscription du net d’impôt dans la réserve de 209 quater, avec arrêt des dotations pour les exercices ouverts depuis 2004.','Aucune inscription, reprise ou reconstitution après entrée en vigueur ; compléments futurs supprimés selon la réforme de 209 quater.','legal_duty','Mères conservant une ancienne réserve spéciale de plus-values.','Anciennes sommes disponibles protégées une seule fois ; faits antérieurs, liquidations et paiements ultérieurs ainsi que recours préservés.','Pas d’état supplémentaire de réserve ; suivi commun de 209.',"Le montant net d'impôt de la plus-value nette à long terme d'ensemble doit être porté, au bilan de la société mère, à la réserve spéciale prévue à l'article 209 quater.","Aucun état supplémentaire de réserve spéciale n'est demandé."),
effect('coordination','is-distribution','Maintien du calcul favorable de groupe sans IS avant distribution.','Plus-value nette d’ensemble imposée séparément selon le a bis du I de 219.','Catégorie et compensation maintenues ; exigibilité seulement à la distribution sous V/VI de 219, sans second emploi des pertes.','regime','Mères et membres réalisant des plus-values ou moins-values à long terme.','Opérations futures et suivi ancien, dans la catégorie et la durée propres de chaque perte.','Affectation des compensations et rapprochement de période dans le suivi annuel de 209.',"La plus-value nette à long terme d'ensemble fait l'objet d'une imposition séparée dans les conditions prévues au a bis du I de l'article 219.","son seul calcul ne rend pas l'IS ordinaire exigible.")])
# 223 E : protéger l'attribution aux filiales en procédure collective, sans double déficit.
x=S[8]['source_xml']
x=replace(x,"dans les conditions prévues par les premier, quatrième ou cinquième alinéas du I (1) de l'article 223 A", "dans les conditions de détention ou de rattachement au groupe prévues à l'article 223 A, appréciées, pour les droits anciens, selon sa rédaction applicable aux exercices d'origine")
x+=paras("Pour les exercices relevant des V et VI de l'article 219, les pertes propres et les droits d'ensemble antérieurs sont suivis et utilisés dans les conditions du XI de l'article 209 et de l'article 223 I, sans double imputation dans une société et dans le groupe. La seule inclusion d'une perte dans un état de suivi sans utilisation fiscale ne vaut pas consommation de cette perte. Une perte effectivement compensée avec une base encore différée n'est plus reportable pour le même montant.",
"La faculté d'attribution prévue au deuxième alinéa demeure ouverte pour les transferts de propriété futurs qui en remplissent les conditions, y compris après l'ouverture du régime de distribution, à concurrence des déficits et moins-values d'ensemble encore disponibles. Par dérogation à toute exigence d'attribution antérieure à cette ouverture, la filiale bénéficiaire peut utiliser la fraction qui lui est ainsi attribuée sur ses assiettes de distributions dans les limites et catégories de report des articles 209, 219 et 39 quindecies. La société mère réduit simultanément son propre droit du même montant ; aucune seconde attribution n'est possible. L'exclusion des fractions susceptibles d'être imputées dans les conditions de l'article 223 G demeure applicable.",
"Le présent article ne crée ni distribution, ni créance remboursable sans impôt acquitté, ni cotisation annuelle d'IS ordinaire sur un bénéfice conservé. Les dix-huit mois, le seuil de 95 %, les trois procédures judiciaires et les droits anciens demeurent dans leur champ ; les dettes, restitutions, prescriptions et recours relatifs aux exercices antérieurs restent régis par leur législation applicable.")
emit(8,x,"Coordination nécessaire : remplacement du renvoi ordinal à 223 A devenu inexact dans sa proposition actuelle, maintien de l'interdiction de double déduction et de l'exception favorable en cas de sortie liée à une procédure collective. L'attribution de droits encore disponibles reste possible pour de futurs transferts éligibles ; elle n'est pas limitée aux attributions déjà réalisées avant l'IS à la distribution.","La proposition de 223 A déplace les réseaux combinés et bancaires dans son II : viser mécaniquement ses anciens quatrième et cinquième alinéas serait erroné. Les 95 %, dix-huit mois, clôture précédente et fraction propre à la filiale restent conservés. 209 XI, 219 V/VI, 223 I et 220 quinquies, cibles non fournies dans reference-targets, ont été consultés dans le corpus. Coordonner expressément 223 I, qui ne doit pas limiter la présente attribution aux seules fractions transférées avant transition ; le texte proposé crée déjà cette dérogation. La ventilation du déficit réduit corrélativement le stock de la mère ; pas d'agrément ou de notification nouvelle. Le contrat unique et son ancienneté ne sont pas concernés.",
'coordination_only',"Le renvoi à la structure nouvelle de 223 A est rectifié. Le droit de sortie pour difficultés judiciaires et sa disponibilité pour les opérations futures sont préservés, avec imputation unique ; aucune baisse fiscale indépendante n'est comptée.","La création de nouveaux déficits d'ensemble ordinaires n'est pas rétablie par cet article. Le droit porte sur des stocks légalement disponibles ; l'article ne promet ni restitution ni transfert libre des pertes.","Aucune charge nouvelle n'est identifiée : l'attribution et la réduction corrélative des stocks existaient dans la source ; elles utilisent le suivi de 209/223 I sans nouvel agrément, délai de notification ou dépôt autonome.",[
effect('coordination','is-distribution','Maintien de l’attribution favorable des droits disponibles lors des futurs transferts judiciaires éligibles.','Attribution d’une fraction du déficit ou de la moins-value d’ensemble à une filiale sortante, avec réduction chez la mère.','Même faculté pour les futurs transferts éligibles, adaptée aux bases de distribution et sans double emploi des stocks.','regime','Filiales sortantes sous le seuil de 95 % dans les conditions judiciaires du deuxième alinéa.','Dix-huit mois en sauvegarde/redressement ou suite à liquidation ; stock disponible à la clôture précédente ; exclusion 223 G maintenue.','Pas de formalité nouvelle ; suivi des stocks attribués et consommés.',"chacune desdites filiales conserve, nonobstant les dispositions du premier alinéa du présent article, le droit d'imputer sur son bénéfice ou ses plus-values nettes à long terme", "La faculté d'attribution prévue au deuxième alinéa demeure ouverte pour les transferts de propriété futurs qui en remplissent les conditions")])
# 223 F : conservation des neutralisations et de leurs dénouements, sans annualité implicite.
x=S[9]['source_xml']
x+=paras("Pour les exercices relevant des V et VI de l'article 219, les règles de neutralisation, de réintégration des suppléments d'amortissement et de reprise du présent article restent applicables à la détermination des résultats de référence, y compris pour les opérations futures remplissant leurs conditions. Les cessions, sorties, pertes de qualité et reprises modifient, à due concurrence, les bases et catégories suivies dans les compartiments du XI de l'article 209. Elles ne constituent pas, par elles-mêmes, des distributions et ne font pas naître un IS ordinaire annuel sur des bénéfices conservés, y compris en trésorerie.",
"La quote-part de frais et charges du troisième alinéa conserve son montant d'assiette et son champ propres aux neutralisations d'exercices ouverts avant le 1er janvier 2019. Pour une opération relevant du nouveau régime, elle est suivie avec la plus-value correspondante et n'est exigible qu'à la distribution dans les conditions du VI de l'article 219. La même plus-value, fraction d'assiette, charge ou perte n'est retenue qu'une fois ; une réintégration déjà comprise dans un compartiment n'est pas ajoutée une seconde fois lors de sa distribution.",
"Les bénéfices antérieurs déjà taxés ou définitivement exonérés sont protégés d'un second IS selon le 1 du XI de l'article 209 ; une simple neutralisation non encore dénouée ne vaut pas taxation antérieure. Les droits et dettes relatifs aux exercices antérieurs, leurs contrôles, restitutions, prescriptions et recours demeurent régis par les règles qui leur étaient applicables, même si leur liquidation, leur exigibilité ou leur paiement est postérieur à l'entrée dans le régime de distribution. Le passage au régime de distribution ne constitue pas une cession, une sortie ou une perte de qualité. Les impositions de sortie faisant perdre à la France son droit d'imposer et l'impôt minimum international conservent leur champ propre.")
emit(9,x,"Coordination nécessaire, sans prétendre supprimer une seconde taxe : conservation de la neutralisation des opérations internes, des corrections d'amortissement, des exclusions et des reprises. Les reprises et quotes-parts alimentent les compartiments du nouvel IS au lieu de rétablir une cotisation annuelle ; aucune neutralisation n'est prise à tort pour un bénéfice déjà taxé.","Le renvoi au 4 de 39 reste une exclusion des biens et dépenses qu'il définit, avec ses justifications et exceptions, non une assimilation générale de tout bien à un avantage personnel. Les dates du 1er janvier 2019 et les alinéas du a ter et du a quinquies de 219 sont conservés. Les propositions de 209 XI/XIII, 219 V/VI et 223 B ont été lues dans le corpus ; 210 A et les clauses de sortie de 221 doivent être coordonnés dans leur champ propre, sans contenu inventé. Ces cibles ne sont pas fournies dans reference-targets. Aucune disparition rétroactive des stocks neutralisés ni extension de la quote-part n'est décidée.",
'coordination_only',"L'avantage de neutralisation et ses contreparties sont conservés pour les situations éligibles. Les reprises n'entraînent plus à elles seules l'exigibilité de l'IS ordinaire avant distribution ; cette coordination ne représente pas une seconde baisse de taux.","Les régimes de fusion, les sorties du droit français d'imposer et le minimum international demeurent distincts ; les comptes et coordinations réglementaires doivent suivre les stocks réellement disponibles.","Aucune charge autonome nouvelle n'est identifiée : les reprises et bases étaient déjà suivies ; leur rattachement aux compartiments communs de 209 ne crée ici ni nouveau dépôt, ni autorisation, ni registre séparé. Le coût du nouveau suivi global de l'IS n'est pas chiffré.",[
effect('coordination','is-distribution','Rattachement des reprises internes aux compartiments sans annualité ordinaire.','Les reprises après cession externe ou sortie du groupe sont comprises dans le résultat ou la plus-value nette d’ensemble.','Reprises maintenues, affectées une seule fois au compartiment ; pas d’IS ordinaire tant que le bénéfice reste conservé.','regime','Sociétés membres, mères et entités intermédiaires visées par 223 F.','Neutralisations anciennes et opérations futures éligibles ; montants déjà exigibles, recours et impositions de sortie préservés.','Pas de formalité spécifique supplémentaire ; suivi commun de 209.',"la société mère doit comprendre dans le résultat ou plus-value ou moins-value nette à long terme d'ensemble, le résultat ou la plus-value ou la moins-value qui n'a pas été retenu lors de sa réalisation.","Le passage au régime de distribution ne constitue pas une cession, une sortie ou une perte de qualité.")])
# 223 G : report en arrière réellement payé, avec adaptation de l'utilisation des créances.
x=S[10]['source_xml']
x=replace(x,"2. Une société filiale du groupe ne peut pas exercer l'option prévue au paragraphe I de l'article 220 quinquies.","2. Pour les exercices soumis au régime d'imposition annuelle du résultat d'ensemble, une société filiale du groupe ne peut pas exercer l'option prévue au paragraphe I de l'article 220 quinquies.")
x+=paras("4. Pour les exercices relevant des V et VI de l'article 219, le report en arrière reste soumis aux conditions de l'article 220 quinquies, notamment son V. Un bénéfice conservé qui n'a supporté aucun IS n'ouvre aucune créance. Une perte éligible du premier exercice nouveau peut être reportée sur le dernier exercice ancien effectivement imposé et non distribué, dans les limites de ce régime. La faculté du a du 1 reste ouverte, dans ces limites, au titulaire légal du déficit d'ensemble ; elle ne transfère pas ce déficit à un autre membre.",
"Le seul regroupement du paiement des distributions ne prive pas un membre de la faculté d'opter au titre de son propre déficit sur son bénéfice antérieur individuellement éligible, dans les conditions de l'article 220 quinquies. Un bénéfice déjà pris en compte dans un résultat d'ensemble ne peut être utilisé une seconde fois à cette fin, conformément à l'article 223 K. Une perte utilisée en report en arrière est simultanément retirée des bases encore différées ou des déficits reportables dans lesquels elle serait également suivie.",
"Les créances antérieures demeurent cessibles à la mère à leur valeur nominale dans les conditions du 3. Pour leur utilisation sur un IS relevant du régime de distribution, la limite prévue à la dernière phrase du 3 est l'IS effectivement dû à raison des distributions de la filiale, déterminé comme si elle était imposée distinctement et avant imputation de cette même créance. Elle n'est pas un impôt annuel théorique sur des bénéfices conservés. L'imputation par la mère éteint à due concurrence la créance disponible chez son titulaire ; elle ne vaut pas un second paiement d'IS ouvrant une nouvelle créance.",
"Les délais d'utilisation et de remboursement, les remboursements anticipés, intérêts et possibilités de transfert restent ceux de l'article 220 quinquies et ne sont pas recommencés par la transition ou la cession. La fraction déjà utilisée ne peut être remboursée. Les exercices antérieurs, créances, dettes, prescriptions et recours restent régis par leurs règles applicables. Le présent article ne crée ni impôt sur un bénéfice conservé ni créance en l'absence d'un impôt antérieurement acquitté et légalement restituable.")
emit(10,x,"Coordination nécessaire du report en arrière avec un IS dû à la distribution : maintien de l'option de la mère, de la cession à valeur nominale des créances des filiales et de leur utilisation plafonnée ; le plafond se calcule sur l'IS de distribution de la filiale, pas sur un impôt annuel fictif. L'interdiction propre à l'ancienne intégration ne ferme pas le report individuel d'un membre du nouveau groupe de paiement sur un bénéfice propre réellement éligible.","220 quinquies et son V ainsi que 209 XI ont été lus dans le corpus autorisé ; cibles non fournies dans reference-targets. Les limites de l'exercice précédent, du million d'euros, des bénéfices non distribués réellement taxés et des cinq ans d'utilisation restent celles de 220 quinquies, avec remboursements anticipés et intérêts conservés. Le b du 1 demeure sans objet et n'est pas renuméroté. Le texte ne crée ni remboursement sur un bénéfice nouveau non taxé ni nouvelle durée de cinq ans ; les droits anciens peuvent encore être utilisés dans leur période propre. Coordonner les formulaires de report en arrière avec 1668 sans déclarer leurs modèles réécrits.",
'coordination_only',"Les créances et les facultés de report légalement ouvertes sont conservées. Le calcul d'utilisation est raccordé aux distributions et le double emploi exclu ; aucun rendement, baisse de taux ou remboursement supplémentaire non fondé n'est revendiqué.","La créance dépend des conditions de 220 quinquies et d'un impôt payé restituable ; le regroupement du paiement ne donne aucun accès général aux pertes d'autrui. Coût et rythme de remboursement non chiffrés.","Aucune charge nouvelle autonome n'est identifiée : l'option, la cession, le plafond et le suivi de consommation des créances préexistent ; aucune déclaration, garantie ni notification spécifique supplémentaire n'est ajoutée.",[
effect('coordination','is-distribution','Adapter l’utilisation des créances de report en arrière à l’IS réellement dû sur les distributions.','Créances pré-intégration cessibles à valeur nominale, utilisables à hauteur de l’IS séparé de la filiale.','Même cession et droit d’utilisation, limite fondée sur l’IS de distribution de la filiale avant cette créance ; aucun impôt théorique annuel.','regime','Mères et filiales titulaires de créances légalement disponibles.','Périodes propres, cinq ans et remboursement anticipé de 220 quinquies conservés ; aucun renouvellement à la cession.','Pas d’option ou de justificatif nouveau ; utilisation unique de la créance.',"les créances constatées par une société filiale du groupe au titre d'exercices précédant celui à compter duquel son résultat a été pris en compte pour la détermination du résultat d'ensemble peuvent être cédées à la société mère à leur valeur nominale.","Elle n'est pas un impôt annuel théorique sur des bénéfices conservés.")])
# 223 H : taux PI et calcul collectif préservés pour les situations futures.
x=S[11]['source_xml']
x=replace(x,"La société mère du groupe soumet à une imposition séparée au taux prévu au deuxième alinéa du a du I de l'article 219 le résultat net d'ensemble de cession, de concession ou de sous-concession des actifs détenus ou pris en concession par une société membre du groupe pour lesquels l'option pour le régime d'imposition prévu à l'article 238 est exercée.","La société mère du groupe détermine, pour son imposition séparée au taux prévu au deuxième alinéa du a du I de l'article 219, le résultat net d'ensemble de cession, de concession ou de sous-concession des actifs détenus ou pris en concession par une société membre du groupe pour lesquels l'option pour le régime d'imposition prévu à l'article 238 est exercée. Pour les exercices relevant des V et VI de l'article 219, la fraction éligible conserve le taux de 10 % du bénéfice avant IS distribué et n'est imposée qu'à sa distribution, dans les conditions du IV du présent article.")
x+=paras("IV. – Pour les exercices relevant des V et VI de l'article 219, les calculs du résultat net d'ensemble, du rapport de dépenses, des pertes et des règles d'entrée et de sortie prévus aux I à III restent ouverts aux groupes et actifs futurs remplissant leurs conditions. Par dérogation à la seule addition des cotisations individuelles prévue à l'article 223 B, le groupe conserve ces mécanismes favorables d'ensemble ; la nouvelle organisation du paiement ne les réserve pas aux actifs ou options antérieurs. "+period,
"La fraction du résultat net d'ensemble éligible après application des pertes et du rapport du 4 du I est affectée aux compartiments de propriété intellectuelle du XI de l'article 209 des membres ayant réalisé des résultats nets positifs pour l'actif, le bien ou service ou la famille de biens ou services concernés. La société mère en répartit le montant, dans la limite du résultat net positif de chaque membre avant application du rapport, sans excéder au total la fraction éligible d'ensemble. Elle identifie cette affectation dans le suivi et le rapprochement annuel déjà prévus à l'article 209, sans dépôt séparé. Le rapport du 4 du I n'est pas appliqué une seconde fois à l'assiette éligible ainsi attribuée. La fraction qui ne relève pas du taux réduit conserve son régime propre.",
"La distribution de la fraction éligible relève du taux de 10 % de son assiette de bénéfice avant IS, dans les conditions de calcul du V de l'article 219. Sans déficit encore légalement imputable, ce taux correspond à 10/90 du montant net attribué au titre de cette fraction avant fiscalité personnelle ; une perte déjà compensée pour déterminer le résultat éligible ne peut être imputée de nouveau. Le simple calcul annuel, la conservation en trésorerie, une rectification du rapport ou une entrée ou sortie du groupe ne rendent pas l'IS ordinaire exigible en l'absence de distribution. Les conditions de conservation du taux favorable et les pertes des I à III restent respectées ; la sortie ne crée pas de droit nouveau sur les pertes du groupe.",
"Une même dépense, perte ou fraction de bénéfice éligible ne peut être utilisée dans plusieurs compartiments, dans le régime individuel de l'article 238 et dans le présent régime d'ensemble, ni lors de plusieurs distributions. Une perte imputée dans le résultat net d'ensemble est retirée du stock encore utilisable de même nature ; elle ne devient pas une perte ordinaire imputable une seconde fois. Les montants déjà taxés ou définitivement exonérés relèvent, pour leur solde réellement disponible, du compte protégé du 1 du XI de l'article 209.",
"Les options et agréments valablement acquis continuent de produire leurs effets dans leur champ ; le seul passage au régime de distribution n'exige pas leur renouvellement. Les droits, dettes, reports, prescriptions, restitutions et recours afférents aux exercices antérieurs restent régis par les règles qui leur étaient applicables, sans second IS lors de la distribution d'un bénéfice déjà taxé. Les régimes distincts et l'impôt minimum international conservent leur champ propre.")
emit(11,x,"Coordination nécessaire : le taux favorable de propriété intellectuelle de 10 % et les calculs de groupe ne sont pas supprimés par l'IS normal à la distribution de 20 %. Le résultat net, les reports négatifs, le rapport de dépenses et les règles d'entrée/sortie restent dans les I à III, avec ouverture aux futures situations éligibles. Le IV reporte l'exigibilité et précise l'affectation aux compartiments individuels pour éviter toute double déduction ; cette ventilation est une charge de calcul à reconnaître.","Lecture complète des I à III et de 238 source, ainsi que de son VIII proposé dans le corpus. Les propositions 209 XI/XIII, 219 V/VI et 223 B ont été consultées ; ce sont des cibles non fournies dans reference-targets. Le taux de 10 % correspond à 10/90 du dividende net, et non à 10 % de ce dividende ; la fraction hors ratio ne prend pas ce taux. Les dépenses du 12 de 39 déterminent la dépendance, pas un contrat de travail. Coordonner la rédaction de 223 B et 223 I pour rendre visible l'exception conservant la compensation collective PI future, déjà opératoire ici, et les annexes de suivi de 238. Le cadre de chiffrage ne supprime pas le CIR ni les autres aides. Le rapprochement de périodes et la ventilation nouvelle ont un coût non chiffré ; aucune conformité internationale ni solde net n'est attesté.",
'mixed',"La protection du taux de 10 % et des mécanismes collectifs est explicite pour les futures situations. L'imposition attend la distribution. L'affectation aux compartiments individuels ajoute un calcul de ventilation ; aucune baisse de taux propre à la PI ni baisse nette globale de complexité n'est revendiquée.","Les conditions de nexus, catégories d'actifs, agréments et reports de 238 restent distinctes. La fraction hors ratio, la fiscalité des associés et le minimum international ne sont pas exonérés ; coût et coordination réglementaire à établir.","Les options et agréments ne sont pas renouvelés du seul fait de la transition. La ventilation du résultat d'ensemble entre compartiments individuels et le rapprochement de périodes constituent un traitement explicité pour le nouvel IS, sans nouveau registre, déclaration séparée ou dépôt de comptes intermédiaires. Le coût net reste inconnu.",[
effect('coordination','is-distribution','Maintenir le taux PI et le calcul de groupe en reportant l’exigibilité à la distribution.','Résultat net d’ensemble éligible imposé séparément au taux PI de 219, avec ratio de dépenses et reports propres.','Taux de 10 % sur l’assiette éligible avant IS ; sans déficit encore imputable, 10/90 du net attribué de cette fraction. Bénéfices conservés non exigibles et mécanismes collectifs futurs préservés.','regime','Groupes exerçant l’option de 238 pour les actifs, biens/services ou familles éligibles.','I à III maintenus, pertes et dépenses à utilisation unique, anciens droits protégés.','Suivi des compartiments de 209 avec affectation du résultat éligible, sans dépôt séparé.',"La société mère du groupe soumet à une imposition séparée au taux prévu au deuxième alinéa du a du I de l'article 219 le résultat net d'ensemble", "la fraction éligible conserve le taux de 10 % du bénéfice avant IS distribué et n'est imposée qu'à sa distribution"),
effect('complexity_added','is-distribution','Affectation du résultat PI de groupe aux compartiments des membres.','Résultat et ratio calculés au niveau d’ensemble par la mère.','Fraction éligible affectée aux membres ayant des résultats positifs, plafonnée à leurs résultats et au total éligible de groupe.','legal_duty','Mère et membres bénéficiaires du régime collectif de propriété intellectuelle.','Nouveaux exercices de distribution ; aucune double prise en compte de résultat ou perte.','Calcul nouveau intégré au suivi annuel de 209 ; coût non chiffré.',"Le résultat net d'ensemble de cession, de concession ou de sous-concession est déterminé par la société mère en faisant la somme algébrique des résultats nets déterminés par chaque société du groupe", "Elle identifie cette affectation dans le suivi et le rapprochement annuel déjà prévus à l'article 209, sans dépôt séparé.")],benefit_review="Le taux de propriété intellectuelle de 10 %, plus favorable que le taux normal proposé de 20 %, demeure ouvert aux futurs actifs et groupes éligibles et n'est exigible qu'à distribution. I.2 conserve la compensation algébrique des résultats des membres ; I.3 conserve les reports négatifs par actif, bien/service ou famille tant que la condition de détention ou sous-concession dans le groupe est satisfaite. I.4 maintient le calcul collectif du rapport, les dépenses directes et indépendantes au numérateur, les dépenses éligibles au dénominateur et, via 238 III, la majoration de 130 %, l'arrondi favorable, le plafond de 100 %, les choix historiques de dépenses et le rapport de remplacement agréé. La limitation aux dépenses de la période de détention dans le groupe reste cohérente avec les règles d'entrée/sortie. II et III ne sont pas des suppressions d'avantages : ils distinguent les pertes antérieures propres des pertes déjà prises en compte par le groupe et évitent le double emploi des dépenses ; la prise en compte des dépenses antérieures à l'entrée reste possible. La valeur vénale d'entrée, restriction source, n'est pas augmentée. IV préserve explicitement le calcul favorable collectif pour les futures situations et interdit sa fermeture par le nouveau simple regroupement du paiement ; aucune créance ancienne ni option valide n'est effacée, aucun renouvellement n'est imposé par la seule transition.")
# 223 K : règle autonome de non-double restitution ; pas de réécriture stylistique.
emit(12,None,"Maintien intégral nécessaire : la règle empêche qu'un déficit postérieur à la sortie donne une seconde restitution sur un bénéfice antérieur déjà intégré. Ce bénéfice n'est pas le bénéfice propre de la filiale pour le report en arrière. La limitation conserve sa fonction sur les anciennes intégrations et sur les futures sorties portant sur ces périodes ; elle ne fixe ni taux d'IS ni prélèvement accessoire à supprimer.","220 quinquies et son V proposé ont été lus dans le corpus ; cible non fournie dans reference-targets. Le renvoi est cohérent avec le dernier bénéfice ancien réellement taxé et non distribué, les limites propres au report et l'absence de créance sur un bénéfice nouveau conservé non imposé. Il n'interdit pas le report sur un bénéfice individuel propre éligible hors résultat d'ensemble. Aucune notification, ancienneté de salarié ou condition du contrat unique n'intervient. Le maintien ne vaut pas validation de toutes les règles de sortie ou des autres restrictions de report.",
'retained_necessary',"Le texte officiel est conservé pour éviter un double remboursement d'IS sur le même bénéfice de groupe. Aucune obligation documentaire distincte, suppression ni économie ne lui est attribuée.","Seule la non-imputation sur le bénéfice déjà intégré est examinée ici ; les autres conditions du report en arrière et les comptes du nouveau régime restent dans leurs articles propres.","Aucune charge nouvelle n'est identifiée : maintien strict de la seule restriction d'imputation existante, sans dossier, agrément, délai ou condition supplémentaire.")
# Analyses des vues requises : l'étiquette générale du fichier ne transforme pas les cibles fiscales en droit du travail.
checks={
0:{'39 bis':"Le renvoi couvre ici les déductions et provisions de presse, dont les périodes historiques et, au 2, les indemnités liées à une ancienneté acquise chez une ancienne entreprise. Source et proposition de 39 bis ont été lues : la suppression du relevé de 223 ter ne supprime ni ces déductions ni leurs conditions. Cette ancienneté historique ne devient pas le seuil d'un an ni le préavis de quinze jours du contrat unique ; aucun recalcul de licenciement n'est opéré."},
1:{'39':"Le 4 de 39 définit les charges de chasse, pêche non professionnelle, résidences, véhicules et plaisance, avec exceptions sociales/professionnelles, seuils automobiles et justifications. La source et la proposition conservent cette subdivision. La comptabilité distincte reste utile à ces exclusions et aux avantages dissimulés, tandis que le vote annuel spécial est retiré. Ni le 1 sur les rémunérations et congés ni le 12 sur la dépendance ne sont des règles d'ancienneté ou de notification du contrat unique.",
'206':"Le renvoi à 206 délimite les personnes passibles de l'IS et exclut expressément son 5 relatif aux revenus patrimoniaux. La proposition de 206 conserve ce 5 et ajoute un 12 sur la distribution en laissant ces régimes distincts. L'exclusion reste donc exacte et n'est ni renumérotée ni supprimée. Le présent retrait du vote annuel ne transforme pas ces revenus en bénéfices distribués ; les renvois sociaux des associations de 5 bis n'introduisent aucun seuil de licenciement."},
2:{'39':"Le dixième alinéa du 5 de 39 est la faculté de demander la justification des frais lorsque leur croissance dépasse celle du bénéfice ou leur montant l'excède ; les catégories a à f et la preuve de l'intérêt de l'entreprise sont conservées dans la vue proposée. L'abrogation retire seulement leur communication particulière à l'assemblée sous responsabilité des commissaires aux comptes. Elle n'efface ni le contrôle de déduction ni le relevé fiscal, et n'a aucun champ de notification ou d'ancienneté salariée."},
4:{'223 A':"Le 4° du I rattache les membres d'un groupe d'intégration à la déclaration simplifiée et le II en confie le dépôt à la mère. La source de 223 A prévoit l'ancienne intégration annuelle ; sa proposition organise un paiement groupé des distributions et préserve les périodes anciennes. L'abrogation retire ce dépôt pour les deux organisations sans utiliser le renvoi pour restaurer un résultat taxable annuel. Le seuil de détention de 95 % concerne le groupe fiscal, non une ancienneté ou un préavis de travail."},
6:{'39':"Le renvoi vise le 12 de 39 pour définir les entreprises liées : détention majoritaire ou pouvoir de décision, et contrôle commun par une tierce entreprise. Source et proposition maintiennent ces deux branches. Elles délimitent la sous-capitalisation, la centralisation de trésorerie et les preuves de ratios, sans assimiler toute dette liée à une distribution. Les seuils et tolérances du VII de 223 B bis restent entiers ; aucune condition d'ancienneté ou de notification de rupture ne s'applique."},
7:{'39 quindecies':"La cible conserve le calcul net, la compensation avec déficit, le report de deux ans des indemnités d'assurance/expropriation et les dix exercices de report des moins-values, ainsi que le ratio de liquidation. Son taux général de 12,8 % n'est pas substitué au taux IS propre de 219 visé par 223 D. La proposition de 223 D conserve les catégories et reports, empêche le double emploi et coordonne l'exigibilité à la distribution ; aucune ancienneté ou notification de licenciement n'est concernée.",
'39':"La sixième disposition de 223 D utilise le seizième alinéa du 5° du 1 de 39 pour les provisions du portefeuille et leurs reprises : source et proposition de 39 conservent cette règle de moins-values/plus-values à long terme. Le correctif de groupe reste symétrique et ne permet pas deux déductions de la même provision ; il alimente le compartiment sans IS ordinaire annuel implicite. Les frais de personnel et le contrat unique ne sont pas le champ de ce renvoi fiscal ordinal.",
'223 L':"La vue est seulement la source officielle de 223 L, sans proposition : les c à j du 6 couvrent fusion, acquisition, scission et recomposition des groupes, dont la sortie judiciaire de h. La dernière phrase de 223 D les utilise pour conserver la reprise favorable de provisions dans un groupe créé ou élargi. Ces références restent utiles aux stocks et droits historiques ; elles doivent être coordonnées avec le paiement des distributions sans rétablir les acomptes annuels, durées d'option ni notifications annuelles de l'ancienne intégration. Aucune règle du contrat privé n'y est attachée."},
8:{'223 A':"La source de 223 E vise les premier, quatrième ou cinquième alinéas du I de 223 A : intégration ordinaire et réseaux combinés/bancaires. Dans la proposition fournie, ces réseaux figurent au II ; la reprise brute des anciens ordinaux serait fausse. Le renvoi est donc rendu descriptif, avec rédaction d'origine pour les droits anciens, et le seuil de 95 % et les dix-huit mois judiciaires restent ceux de 223 E. Ils ne sont ni une ancienneté d'emploi ni un préavis individuel. Les futurs transferts éligibles conservent l'accès aux stocks disponibles."},
9:{'39':"Le dernier alinéa de 223 F exclut les biens du 4 de 39 du régime des cessions internes. La source et la proposition de la cible conservent les biens visés, justifications et exceptions ; ce renvoi n'est donc pas effacé avec le passage à la distribution. Une dépense professionnelle réelle n'est pas requalifiée systématiquement en distribution personnelle. La référence à 39 B sur l'amortissement reste distincte du présent contrôle ; aucune condition de notification ou d'ancienneté du contrat unique n'est introduite."},
11:{'39':"Le 12 de 39 sert dans le numérateur du rapport de dépenses à déterminer quelles entreprises de recherche sont sans lien de dépendance avec un membre du groupe. Ses critères de contrôle direct, indirect ou commun restent inchangés dans la vue proposée et sont conservés dans le texte de 223 H. Ils ne visent ni une durée de formation ni la durée de l'emploi. La conservation du taux PI futur et du calcul collectif n'élargit pas le numérateur aux dépenses liées et n'ajoute aucun seuil d'ancienneté ou notification de rupture."}
}
for i,a in enumerate(A):
    req=R['requirements'][a['code_id']+'|'+a['source_id']]
    out=[]
    for key in req:
        t=R['targets'][key]
        out.append(dict(target_key=key,view_sha256=t['view_sha256'],assessment=checks[i][t['number']]))
    assert len(checks.get(i,{}))==len(req)
    a['reference_checks']=out
# Compléter explicitement les conséquences documentaires et la coordination de la réserve.
d=A[7]
d.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=["Obligation d'inscription, reprise ou reconstitution de l'ancienne réserve spéciale de 209 quater et complément d'IS par renvoi pour les prélèvements futurs, en coordination avec la même suppression dans 209 quater."])
d['substantive_impact']['effects'].append(effect('complexity_added','is-distribution','Affectation des compensations de moins-values aux compartiments des membres.','Compensation calculée dans la plus-value ou moins-value nette d’ensemble.','Compensation ventilée aux bases des gains des membres, limitée à la catégorie et au montant des gains.','legal_duty','Mères et membres bénéficiant de la compensation à long terme de groupe.','Nouveau régime, droits anciens et futurs éligibles conservés ; perte imputée consommée une seule fois.','Ventilation et rapprochement dans le suivi de 209, sans état supplémentaire de réserve.',"Les dispositions de l'article 39 quindecies sont applicables à la plus-value et à la moins-value nette à long terme d'ensemble.","La société mère affecte la compensation effectivement utilisée aux bases des gains des membres concernés dans le suivi du XI de l'article 209 et le rapprochement annuel, dans la limite des gains de la catégorie correspondante."))
d['proposed_xml']+='\n'+paras("Pour les opérations nouvelles relevant du régime de distribution, le renvoi aux c à j du 6 de l'article 223 L, au sixième alinéa du présent article, conserve la continuité favorable des provisions lors des fusions, acquisitions, scissions et recompositions qu'ils décrivent. Les sociétés sont appréciées dans le périmètre du groupe de l'article 223 A en vigueur pour la période concernée. Ce renvoi ne rétablit ni une durée minimale d'option, ni un alignement des clôtures, ni un acompte ou une notification annuelle supprimés dans ce régime ; les conditions de fond de l'opération et de non-double déduction restent applicables. Les opérations anciennes et leurs droits de provision restent appréciés selon les textes qui leur étaient applicables.")
d['proposed_xml']+='\n'+paras("Dans son champ propre, le report favorable de deux ans prévu au 1 du I de l'article 39 quindecies demeure applicable ; une distribution antérieure à son échéance ne l'abrège pas. L'exception de cessation d'activité prévue par cet article conserve son champ, avec les règles d'imposition de sortie et de non-double imposition des articles 209, 219 et 221. La compensation avec un déficit d'exploitation, le report de dix exercices des moins-values et la déduction possible à la liquidation dans le rapport prévu au 2 du I de l'article 39 quindecies ne sont pas fermés par le présent article.")
d['review_notes']+=" Le report favorable de deux ans de 39 quindecies est expressément maintenu, avec son exception de cessation, sans raccourcissement par une distribution ; les dix exercices et le ratio de liquidation restent applicables dans leur catégorie."
# Citations prises dans des alinéas entiers pour garder leurs conditions visibles.
