A[9]['substantive_impact']['effects'][0]['source_quote']=source_p(9,1)
A[10]['substantive_impact']['effects'][0]['source_quote']=source_p(10,4)
A[11]['substantive_impact']['effects'][0]['source_quote']=source_p(11,0)
