# Vérifications de structure et d'intégrité textuelle, sans prétention d'audit juridique.
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
assert len(A)==13
for s,a in zip(S,A):
    for k in ['code_id','source_id','source_sha256','number']: assert a[k]==s[k]
    p=a['proposed_xml'];impact=a['substantive_impact']
    assert a['status'] in {'rewrite_draft','retained_unchanged'}
    if p is None:
        assert a['status']=='retained_unchanged' and impact['classification']=='retained_necessary' and not impact['effects']
    else:
        assert p and 'texte inchangé' not in p.lower()
        from xml.etree import ElementTree as ET
        root=ET.fromstring('<root>'+p+'</root>')
        for el in root.iter():
            if el.tag=='root': continue
            assert el.tag in allowed, (a['number'],el.tag)
            for k,v in el.attrib.items(): assert k in {'rowspan','colspan'} and v.isnumeric()
    for k in ['assessment','scope_limitations','new_burdens_review']: assert len(impact[k])>=40
    if s.get('benefit_check_required'): assert len(a.get('benefit_review',''))>=100
    if a.get('change_type')=='full_repeal':
        assert plain(p).startswith(('Le présent article est abrogé','Abrogé'))
        assert len(a['repeal_scope'])>=30 and a['repeal_policy_id']=='editorial_direction_2026_10_19'
    if a.get('change_type')=='normative_reduction':
        assert a['reform_policy_id']=='editorial_direction_2026_10_19'
        assert a['removed_provisions'] and all(len(v)>=30 for v in a['removed_provisions'])
    for e in impact['effects']:
        assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
        for field,body in [('source_quote',s['source_xml']),('proposed_quote',p)]:
            assert len(e[field])>=12 and e[field] in plain(body),(a['number'],field,e[field])
    req=R['requirements'][a['code_id']+'|'+a['source_id']]
    assert [c['target_key'] for c in a['reference_checks']]==req
    for c in a['reference_checks']:
        assert c['view_sha256']==R['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
Path('answer.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
for a in A: print(a['number'],a['status'],a['substantive_impact']['classification'],len(a['proposed_xml'] or ''),len(a['reference_checks']))
print('answer.json :',len(A),'articles, citations exactes et structure contrôlées ; aucune validation juridique indépendante.')
